-- security_nov22: shared guard, included at the top of every migration here (01-04). Safe to run many times.
-- pb_sec.guard(tag, function, md5): refuses (and so rolls the whole migration back) when the live definition of a
-- function we replace is not the one read on Nov 21 2026. When it matches, the live definition is saved first in
-- pb_sec.fn_backup, so the undo files put back the exact text that was live (no copy typed by hand).
-- Running a migration a second time: the backup row is already there, so it goes through again.
create schema if not exists pb_sec;
revoke all on schema pb_sec from public;
revoke all on schema pb_sec from anon, authenticated;
create table if not exists pb_sec.fn_backup (
  tag      text not null,          -- which migration (nov22_01 ...)
  sig      text not null,          -- regprocedure text, e.g. public.pb_session_gate()
  def      text not null,          -- pg_get_functiondef() as it was live
  md5      text not null,
  saved_at timestamptz not null default now(),
  primary key (tag, sig)
);
alter table pb_sec.fn_backup enable row level security;
revoke all on table pb_sec.fn_backup from public;
revoke all on table pb_sec.fn_backup from anon, authenticated;

create or replace function pb_sec.guard(p_tag text, p_sig text, p_md5 text) returns void
language plpgsql set search_path = '' as $f$
declare v_def text; v_md5 text;
begin
  v_def := pg_get_functiondef(p_sig::regprocedure);
  v_md5 := md5(v_def);
  if v_md5 = p_md5 then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  if exists (select 1 from pb_sec.fn_backup b where b.tag = p_tag and b.sig = p_sig) then return; end if; -- this migration ran before
  -- (throwaway local test database only: the stand-in functions there are not the live text)
  if current_setting('pb_sec.guard', true) = 'skip-local-test' then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  raise exception 'pb_sec: % changed on live since Nov 21 2026 (md5 % , expected %). Nothing was applied. Re-read it and rebase this migration.', p_sig, v_md5, p_md5;
end $f$;
revoke all on function pb_sec.guard(text, text, text) from public;
revoke all on function pb_sec.guard(text, text, text) from anon, authenticated;

-- undo helper: puts back every function a migration replaced, exactly as it was live
create or replace function pb_sec.restore(p_tag text) returns integer
language plpgsql set search_path = '' as $f$
declare r record; n integer := 0;
begin
  for r in select b.sig, b.def from pb_sec.fn_backup b where b.tag = p_tag order by b.sig loop
    execute r.def; n := n + 1;
  end loop;
  delete from pb_sec.fn_backup where tag = p_tag;
  return n;
end $f$;
revoke all on function pb_sec.restore(text) from public;
revoke all on function pb_sec.restore(text) from anon, authenticated;

-- security_nov22 03 (review finding 3, MEDIUM): someone removed from a company loses control of what they uploaded to it.
-- Before: the uploader test was "provenance.user_id = me" / "sets.created_by = me" with no look at the company, so after
-- removal the person could still remove, re-scope (incl. to the shared library), re-tag, resume and re-text the company's
-- documents, remove the company's plan sets, and keep uploading files into a plan set still 'uploading'.
-- After: the uploader side of each check also needs the item's company to still be theirs (pb_prod.my_company, or the
-- company they manage). Items with no company (an individual's own) are unchanged. The office side is unchanged.
--   pb_docs.can_manage(doc)       used by pb_docs_set_jobs / set_area / resume, public.pb_docs_can_manage (the docs edge
--                                 function asks it with the caller's token), pb_docs.label, pb_docs_mine
--   public.pb_docs_remove         had its own copy of the old test: now calls pb_docs.can_manage
--   public.pb_docs_set_scope      its own test: uploader side now needs the company
--   public.pb_docs_put_pages      uploader only: now needs the company
--   public.pb_plans_remove        created_by side now needs the company
--   pb_plans.can_upload_to(name)  (storage upload policy for plan sheets) now needs the company
-- New: pb_docs.still_in(company, user). Run as postgres, in one transaction (the whole file). Safe to run twice.
-- Undo: undo/99_undo_03.sql.

select pb_sec.guard('nov22_03', 'pb_docs.can_manage(uuid)', '329db9059772346be0eea6db683cfc6a');
select pb_sec.guard('nov22_03', 'public.pb_docs_remove(uuid)', 'f6c2ddfca7ace66c596408daa60a6ccf');
select pb_sec.guard('nov22_03', 'public.pb_docs_set_scope(uuid,text)', 'eb2ae90cbfa100b0260a7540de6d6e55');
select pb_sec.guard('nov22_03', 'public.pb_docs_put_pages(uuid,jsonb)', '16519bf38a307b292fad8d859fcf121f');
select pb_sec.guard('nov22_03', 'public.pb_plans_remove(uuid)', 'bf385c93f29fd0a717527ae82873cba3');
select pb_sec.guard('nov22_03', 'pb_plans.can_upload_to(text)', '41155e884364ceb0101a9a3028abffec');

-- true when an item filed under p_company is still the user's to manage as its uploader: no company (their own item),
-- or the company they are a member of now, or the company they own / manage now
create or replace function pb_docs.still_in(p_company uuid, p_uid uuid) returns boolean
language sql stable security definer set search_path = '' as $f$
  select p_uid is not null and (p_company is null
    or p_company is not distinct from pb_prod.my_company(p_uid)
    or p_company is not distinct from pb_prod.managed_company(p_uid))
$f$;
revoke all on function pb_docs.still_in(uuid, uuid) from public;
revoke all on function pb_docs.still_in(uuid, uuid) from anon, authenticated;

CREATE OR REPLACE FUNCTION pb_docs.can_manage(p_doc uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from pb_docs.provenance p where p.doc_id = p_doc
    and ((p.user_id = auth.uid() and pb_docs.still_in(p.company_id, auth.uid()))   -- security_nov22 03: uploader still in the company
      or (p.company_id is not null and p.company_id = pb_prod.managed_company(auth.uid()))))
$function$;

CREATE OR REPLACE FUNCTION public.pb_docs_remove(p_doc uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  -- security_nov22 03: the one shared test (it was a copy of the old one here)
  if not pb_docs.can_manage(p_doc) then
    return jsonb_build_object('ok', false, 'code', 'pb:not_yours'); end if;
  perform pb_docs.purge(p_doc);
  return jsonb_build_object('ok', true);
end $function$;

CREATE OR REPLACE FUNCTION public.pb_docs_set_scope(p_doc uuid, p_scope text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v pb_docs.provenance; d pb_docs.documents; v_key text; v_ok text;
begin
  if auth.uid() is null then raise exception 'pb:signed_out'; end if;
  -- second review SR8: only the uploader, or the office of the uploader's company.
  -- security_nov22 03: the uploader only while still in that company.
  select * into v from pb_docs.provenance p where p.doc_id = p_doc
    and ((p.user_id = auth.uid() and pb_docs.still_in(p.company_id, auth.uid()))
      or (p.company_id is not null and p.company_id = pb_prod.managed_company(auth.uid())));
  if not found then return jsonb_build_object('ok', false, 'code', 'pb:not_yours'); end if;
  v_key := pb_docs.owner_key(v.company_id, v.user_id);
  perform pb_docs.lock(v_key);
  select * into d from pb_docs.documents where id = p_doc for update;
  if d.state <> 'live' then return jsonb_build_object('ok', false, 'code', 'pb:not_ready'); end if;
  if p_scope = 'private' then
    perform pb_docs.apply_scope(p_doc, 'private');
    update pb_docs.provenance set user_choice = 'private' where doc_id = p_doc;
    return jsonb_build_object('ok', true, 'scope', 'private');
  elsif p_scope = 'shared' then
    if d.scope = 'shared' then return jsonb_build_object('ok', true, 'scope', 'shared'); end if;
    perform pb_docs.lock_sha(d.sha256);
    if not d.shareable or d.public_title is null then return jsonb_build_object('ok', false, 'code', 'pb:not_public', 'message', 'Only public codes, specs and data sheets the app could check against the publisher can be shared.'); end if;
    if exists (select 1 from pb_docs.documents x where x.sha256 = d.sha256 and x.scope = 'shared' and x.state <> 'removed' and x.id <> d.id) then
      return jsonb_build_object('ok', false, 'code', 'pb:already_shared', 'message', 'This document is already in the shared library.'); end if;
    v_ok := pb_docs.take_share(v_key, auth.uid(), p_doc, 'switch');
    if v_ok = 'blocked' then return jsonb_build_object('ok', false, 'code', 'pb:share_blocked', 'message', 'Sharing is paused for your company. Contact support.'); end if;
    if v_ok = 'rate' then return jsonb_build_object('ok', false, 'code', 'pb:rate', 'message', 'That''s today''s sharing limit. Try again tomorrow.'); end if;
    perform pb_docs.apply_scope(p_doc, 'shared');
    update pb_docs.provenance set user_choice = 'shared' where doc_id = p_doc;
    return jsonb_build_object('ok', true, 'scope', 'shared');
  end if;
  return jsonb_build_object('ok', false, 'code', 'pb:bad_scope');
end $function$;

CREATE OR REPLACE FUNCTION public.pb_docs_put_pages(p_doc uuid, p_pages jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_n integer := 0; p jsonb; d pb_docs.documents; v_company uuid; v_chars bigint; v_new bigint; v_max integer;
begin
  if auth.uid() is null then raise exception 'pb:signed_out'; end if;
  -- security_nov22 03: the uploader only while still in the document's company
  select d2.* into d from pb_docs.documents d2 join pb_docs.provenance pv on pv.doc_id = d2.id
    where d2.id = p_doc and pv.user_id = auth.uid() and pb_docs.still_in(pv.company_id, auth.uid()) and d2.state = 'uploading' for update of d2;
  if d.id is null then return jsonb_build_object('ok', false, 'code', 'pb:not_yours'); end if;
  if jsonb_typeof(p_pages) <> 'array' or jsonb_array_length(p_pages) > 100 then return jsonb_build_object('ok', false, 'code', 'pb:bad_pages'); end if;
  select company_id into v_company from pb_docs.provenance where doc_id = p_doc;
  v_max := coalesce(d.pages, 1);
  if exists (select 1 from jsonb_array_elements(p_pages) x where jsonb_typeof(x->'n') <> 'number' or (x->>'n')::numeric <> floor((x->>'n')::numeric) or (x->>'n')::int not between 1 and v_max) then
    return jsonb_build_object('ok', false, 'code', 'pb:bad_page_number', 'max', v_max); end if;
  select coalesce(sum(length(g.text)), 0) into v_chars from pb_docs.pages g where g.doc_id = p_doc and g.n not in (select (x->>'n')::int from jsonb_array_elements(p_pages) x);
  select coalesce(sum(least(length(coalesce(x->>'text', '')), 40000)), 0) into v_new from jsonb_array_elements(p_pages) x;
  if v_chars + v_new > pb_docs.chars_cap(d.bytes, pb_docs.limits_for(v_company)) then return jsonb_build_object('ok', false, 'code', 'pb:too_much_text'); end if;
  if pb_docs.stored_bytes(pb_docs.owner_key(v_company, auth.uid())) + v_new > (pb_docs.limits_for(v_company)->>'bytes_total')::bigint then return jsonb_build_object('ok', false, 'code', 'pb:storage_full'); end if;
  for p in select * from jsonb_array_elements(p_pages) loop
    insert into pb_docs.pages (doc_id, n, text, source) values (p_doc, (p->>'n')::int, left(coalesce(p->>'text', ''), 40000), 'pdf_text')
      on conflict (doc_id, n) do update set text = excluded.text, source = 'pdf_text';
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'pages', v_n);
end $function$;

CREATE OR REPLACE FUNCTION public.pb_plans_remove(p_set uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_s pb_plans.sets; c record; v_found boolean;
begin
  if auth.uid() is null then raise exception 'pb:signed_out'; end if;
  select * into v_s from pb_plans.sets where id = p_set;
  v_found := found;
  select * into c from pb_ai.ctx();
  -- security_nov22 03: the person who added it only while still in the set's company
  if not v_found or not coalesce((v_s.created_by = auth.uid() and pb_docs.still_in(v_s.company_id, auth.uid()))
        or (c.level = 'office' and c.company_id is not null and v_s.company_id is not null and c.company_id = v_s.company_id), false) then
    return jsonb_build_object('ok', false, 'code', 'pb:not_yours', 'message', 'Only the person who added it or the office can remove it.');
  end if;
  update pb_plans.sets set state = 'removed', removed_at = now() where id = p_set;
  return jsonb_build_object('ok', true);
end $function$;

CREATE OR REPLACE FUNCTION pb_plans.can_upload_to(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from pb_plans.sets s where s.id::text = split_part(p_name, '/', 1) and s.created_by = auth.uid() and s.state = 'uploading'
    and pb_docs.still_in(s.company_id, auth.uid()))  -- security_nov22 03
$function$;

-- security_nov22 03 test: a removed uploader loses control of the company's documents and plan sets. Ends with 'RESULT: ...'.
create function pg_temp.s3_as(p_user uuid) returns void language sql as $f$
  select set_config('request.jwt.claims', jsonb_build_object('role', 'authenticated', 'sub', p_user, 'aal', 'aal1')::text, true); $f$;
create function pg_temp.s3_j(p_user uuid, p_what text, p_doc uuid) returns text language plpgsql as $f$
declare j jsonb; b boolean;
begin
  perform pg_temp.s3_as(p_user);
  if p_what = 'can' then b := pb_docs.can_manage(p_doc); return b::text; end if;
  if p_what = 'can_api' then b := public.pb_docs_can_manage(p_doc); return b::text; end if;
  if p_what = 'remove' then j := public.pb_docs_remove(p_doc);
  elsif p_what = 'private' then j := public.pb_docs_set_scope(p_doc, 'private');
  elsif p_what = 'jobs' then j := public.pb_docs_set_jobs(p_doc, array['J9']);
  elsif p_what = 'pages' then j := public.pb_docs_put_pages(p_doc, '[{"n": 1, "text": "hello"}]'::jsonb);
  elsif p_what = 'plan_remove' then j := public.pb_plans_remove(p_doc);
  elsif p_what = 'plan_upload' then b := pb_plans.can_upload_to(p_doc::text || '/sheet-1.png'); return b::text;
  end if;
  return coalesce(j->>'code', case when (j->>'ok')::boolean then 'ok' else 'not ok' end);
exception when others then return 'ERR ' || sqlerrm; end $f$;

do $test$
declare
  pass integer; fail integer; fails text; notes text := ''; tag text := substr(md5(random()::text), 1, 10);
  o uuid := gen_random_uuid(); m uuid := gen_random_uuid(); m2 uuid := gen_random_uuid(); solo uuid := gen_random_uuid(); o2 uuid := gen_random_uuid();
  c uuid := gen_random_uuid(); c2 uuid := gen_random_uuid();
  d1 uuid := gen_random_uuid(); d2 uuid := gen_random_uuid(); d3 uuid := gen_random_uuid(); d4 uuid := gen_random_uuid(); d5 uuid := gen_random_uuid();
  s1 uuid := gen_random_uuid(); s2 uuid := gen_random_uuid(); s3 uuid := gen_random_uuid(); s4 uuid := gen_random_uuid(); x text;
begin
  create temp table t_chk (i serial, name text, ok boolean, got text) on commit drop;
  insert into auth.users (id, email) select v, 'pbsec03-' || tag || '-' || row_number() over () || '@example.invalid' from unnest(array[o, m, m2, solo, o2]) v;
  insert into public.companies (id, name, owner_user_id, status, plan) values (c, 'pbsec03 ' || tag, o, 'active', 'trial'), (c2, 'pbsec03b ' || tag, o2, 'active', 'trial');
  insert into public.company_members (company_id, user_id, role) values (c, m, 'foreman'), (c, m2, 'foreman');
  -- documents: d1, d3 (uploading), d4 by m in c; d5 by m2 in c; d2 by someone with no company
  -- (live checks: a private doc has exactly one owner, company OR person; sha256 is 64 hex)
  insert into pb_docs.documents (id, owner_company, owner_user, state, title, mime, sha256, pages) values
    (d1, c, null, 'live', 't1', 'application/pdf', md5('s1' || tag) || md5('x'), 1), (d2, null, solo, 'live', 't2', 'application/pdf', md5('s2' || tag) || md5('x'), 1),
    (d3, c, null, 'uploading', 't3', 'application/pdf', md5('s3' || tag) || md5('x'), 1), (d4, c, null, 'live', 't4', 'application/pdf', md5('s4' || tag) || md5('x'), 1),
    (d5, c, null, 'uploading', 't5', 'application/pdf', md5('s5' || tag) || md5('x'), 1);
  insert into pb_docs.provenance (doc_id, company_id, user_id, sha256) values (d1, c, m, md5('s1' || tag) || md5('x')), (d2, null, solo, md5('s2' || tag) || md5('x')),
    (d3, c, m, md5('s3' || tag) || md5('x')), (d4, c, m, md5('s4' || tag) || md5('x')), (d5, c, m2, md5('s5' || tag) || md5('x'));
  insert into pb_plans.sets (id, company_id, created_by, job_key, job_number, title, pages, sha256, state) values
    (s1, c, m, 'j1', 'J1', 'p1', 1, 'x1' || tag, 'uploading'), (s2, c, m2, 'j1', 'J1', 'p2', 1, 'x2' || tag, 'uploading'),
    (s3, null, solo, 'j1', 'J1', 'p3', 1, 'x3' || tag, 'uploading'), (s4, c, m, 'j1', 'J1', 'p4', 1, 'x4' || tag, 'ready');

  x := pg_temp.s3_j(m, 'can', d1) || '/' || pg_temp.s3_j(m, 'can_api', d1) || '/' || pg_temp.s3_j(m, 'plan_upload', s1);
  insert into t_chk (name, ok, got) values ('3a uploader still in the company: manages the doc, uploads plan sheets', x = 'true/true/true', x);

  delete from public.company_members where user_id = m and company_id = c;   -- removed
  x := pg_temp.s3_j(m, 'can', d1) || '/' || pg_temp.s3_j(m, 'can_api', d1);
  insert into t_chk (name, ok, got) values ('3b removed uploader: can_manage false (also what the docs edge function asks)', x = 'false/false', x);
  x := pg_temp.s3_j(m, 'remove', d1);
  insert into t_chk (name, ok, got) select '3c removed uploader: remove refused, doc still there', x = 'pb:not_yours' and (select state from pb_docs.documents where id = d1) = 'live', x;
  x := pg_temp.s3_j(m, 'private', d1);
  insert into t_chk (name, ok, got) values ('3d removed uploader: change scope refused', x = 'pb:not_yours', x);
  x := pg_temp.s3_j(m, 'jobs', d1);
  insert into t_chk (name, ok, got) values ('3e removed uploader: re-tag jobs refused', x = 'not ok', x);
  x := pg_temp.s3_j(m, 'pages', d3);
  insert into t_chk (name, ok, got) values ('3f removed uploader: put page text refused', x = 'pb:not_yours', x);
  x := pg_temp.s3_j(m, 'plan_remove', s4) || '/' || pg_temp.s3_j(m, 'plan_upload', s1);
  insert into t_chk (name, ok, got) select '3g removed uploader: plan set remove refused, sheet upload refused', x = 'pb:not_yours/false' and (select state from pb_plans.sets where id = s4) = 'ready', x;
  insert into public.company_members (company_id, user_id, role) values (c2, m, 'foreman');
  x := pg_temp.s3_j(m, 'can', d1) || '/' || pg_temp.s3_j(m, 'plan_upload', s1);
  insert into t_chk (name, ok, got) values ('3h joined another company: still nothing on the old company''s items', x = 'false/false', x);
  -- the office keeps control
  x := pg_temp.s3_j(o, 'can', d1) || '/' || pg_temp.s3_j(o, 'jobs', d1) || '/' || pg_temp.s3_j(o, 'private', d1) || '/' || pg_temp.s3_j(o, 'remove', d4) || '/' || pg_temp.s3_j(o, 'plan_remove', s4);
  insert into t_chk (name, ok, got) values ('3i the owner (office) still manages them: can/jobs/scope/remove/plan remove', x = 'true/ok/ok/ok/ok', x);
  -- uploaders still in the company: unchanged
  x := pg_temp.s3_j(m2, 'pages', d5) || '/' || pg_temp.s3_j(m2, 'plan_upload', s2) || '/' || pg_temp.s3_j(m2, 'plan_remove', s2);
  insert into t_chk (name, ok, got) values ('3j an uploader still in the company: pages/upload/remove plan unchanged', x = 'ok/true/ok', x);
  -- another member who did not upload it: no
  x := pg_temp.s3_j(m2, 'can', d1);
  insert into t_chk (name, ok, got) values ('3k a crew member who did not upload it: no', x = 'false', x);
  -- someone with no company: their own items unchanged
  x := pg_temp.s3_j(solo, 'can', d2) || '/' || pg_temp.s3_j(solo, 'private', d2) || '/' || pg_temp.s3_j(solo, 'plan_upload', s3) || '/' || pg_temp.s3_j(solo, 'remove', d2);
  insert into t_chk (name, ok, got) values ('3l individual (no company): own doc and plan set unchanged', x = 'true/ok/true/ok', x);
  -- a company that is no longer active: its former uploader no, its owner neither (managed_company needs active) - as before for the office
  insert into t_chk (name, ok, got) values ('3m still_in is not callable from the API',
    not has_function_privilege('authenticated', 'pb_docs.still_in(uuid,uuid)', 'execute') and not has_function_privilege('anon', 'pb_docs.still_in(uuid,uuid)', 'execute'), '');
  insert into t_chk (name, ok, got) select '3n six live functions saved for undo', (select count(*) from pb_sec.fn_backup where fn_backup.tag = 'nov22_03') = 6, '';
  perform pb_sec.restore('nov22_03');
  x := pg_temp.s3_j(m, 'can', d1);
  insert into t_chk (name, ok, got) values ('3o undo (restore) brings back the old test (live: removed uploader true again)', x = case when current_setting('pb_sec.guard', true) = 'skip-local-test' then 'false' else 'true' end, x);

  select count(*) filter (where ok), count(*) filter (where ok is not true), coalesce(string_agg(name || ' [got: ' || coalesce(got, 'null') || ']', ' ; ' order by i) filter (where ok is not true), '') into pass, fail, fails from t_chk;
  raise exception 'RESULT: % pass, % fail% %', pass, fail, case when fail > 0 then ' | FAILED: ' || fails else '' end, notes;
end $test$;

rollback;
